SELECT DISTINCT knowledge_id
FROM knowledge_acl
WHERE status = #{status}
  AND (effective_time IS NULL OR effective_time <= #{effectiveAt})
  AND (expire_time IS NULL OR expire_time > #{effectiveAt})
  AND (


            OR (subject_type = #{roleSubjectType} AND subject_id IN

                #{roleId}
            )


            OR (subject_type = #{deptSubjectType} AND include_children = #{includeChildren}
            AND subject_id IN

                #{deptId}
            )


            OR (subject_type = #{deptSubjectType} AND include_children = #{excludeChildren}
            AND subject_id = #{directDeptId})


  )
